/// Render as inline SVG (`fill` follows the button foreground). Unknown names give an empty string.
pub fn svg(name: &str, fg: &str) -> String {
    let Some(inner) = ICONS.iter().find(|(n, _)| *n == name).map(|(_, m)| *m) else {
        return String::new();
    };
    format!(
        "<svg viewBox=\"0 0 32 32\" width=\"13\" height=\"13\" \
         xmlns=\"http://www.w3.org/2000/svg\" fill=\"{fg}\">{inner}</svg>"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_icons_render_svg() {
        for (name, _) in ICONS {
            let s = svg(name, "#ffffff");
            assert!(s.starts_with("<svg"), "{name}");
            assert!(s.contains("fill=\"#ffffff\""), "{name}");
        }
    }

    #[test]
    fn unknown_icon_is_empty() {
        assert!(svg("nope", "#fff").is_empty());
    }
}
